INSERT INTO SUBPARTIDA (id_subpartida, codigo_10digitos, descripcion, es_terminal, fk_partida, fk_unidad, fk_subpartida_padre) VALUES (9880, '6006.90.00.00', '- Los demás 26 m² CAPÍTULO 61 PRENDAS Y COMPLEMENTOS (ACCESORIOS), DE VESTIR, DE PUNTO Notas. 1. Este Capítulo solo comprende artículos de punto confeccionados. 2. Este Capítulo no comprende: a) los artículos de la partida 62.12; b) los artículos de prendería de la partida 63.09; c) los artículos de ortopedia, tales como bragueros para hernias, fajas medicoquirúrgicas (partida 90.21). 3. En las partidas 61.03 y 61.04: a) se entiende por trajes (ambos o ternos) y trajes sastre los surtidos formados por dos o tres prendas de vestir confeccionadas en su superficie exterior con la misma tela y compuestos por: - una sola chaqueta (saco) que cubra la parte superior del cuerpo, cuyo exterior, excepto las mangas, esté constituido por cuatro o más piezas, eventualmente acompañada de un solo chaleco sastre en el que su parte delantera esté confeccionada con la misma tela que la superficie exterior de los demás componentes del surtido y cuya espalda sea de la misma tela que el forro de la chaquet', 1, 683, NULL, NULL);
